// Set to FALSE to let tall followers walk indoors as well (they will then overlap walls/ceilings of small rooms).
#define FOLLOWER_TALL_HIDDEN_IN_BUILDINGS TRUE

// ENTRY P84: the lead's form and gender are only read when the species actually has a FOLLOWER_FORM_TABLE row that
// needs them. This runs every field frame (FollowerMon_Refresh), and Pokemon_GetGender is not free - it loads the
// species' personal data - so for the ~490 single-form species the form table costs only a species compare per row.
// A species whose rows are all form 0 (the gender-only ones: Venusaur, Pikachu, Garchomp, ...) treats its gender rows
// as matching every form.
static u16 FollowerMon_GetGraphicsID(Pokemon *mon, u16 species)
{
    u32 first = FOLLOWER_FORM_TABLE_COUNT;
    BOOL needsForm = FALSE;
    BOOL needsGender = FALSE;

    for (u32 i = 0; i < FOLLOWER_FORM_TABLE_COUNT; i++) {
        const FollowerFormEntry *entry = &FOLLOWER_FORM_TABLE[i];

        if (entry->species == species) {
            if (first == FOLLOWER_FORM_TABLE_COUNT) {
                first = i;
            }
            if (entry->form != 0) {
                needsForm = TRUE;
            }
            if (entry->gender != FOLLOWER_GENDER_ANY) {
                needsGender = TRUE;
            }
        }
    }

    if (first != FOLLOWER_FORM_TABLE_COUNT) {
        u8 form = needsForm ? Pokemon_GetValue(mon, MON_DATA_FORM, NULL) : 0;
        u8 gender = needsGender ? Pokemon_GetGender(mon) : FOLLOWER_GENDER_ANY;

        for (u32 i = first; i < FOLLOWER_FORM_TABLE_COUNT; i++) {
            const FollowerFormEntry *entry = &FOLLOWER_FORM_TABLE[i];

            if (entry->species == species && entry->form == form
                && (entry->gender == FOLLOWER_GENDER_ANY || entry->gender == gender)) {
                return entry->graphicsID;
            }
        }
    }

    for (u32 i = 0; i < FOLLOWER_GRAPHICS_TABLE_COUNT; i++) {
        if (FOLLOWER_GRAPHICS_TABLE[i].species == species) {
            return FOLLOWER_GRAPHICS_TABLE[i].graphicsID;
        }
    }
    return FOLLOWER_GRAPHICS_NONE;
}

static BOOL FollowerMon_IsTallGraphics(u16 graphicsID)
{
    for (u32 i = 0; i < FOLLOWER_TALL_TABLE_COUNT; i++) {
        if (FOLLOWER_TALL_TABLE[i] == graphicsID) {
            return TRUE;
        }
    }
    return FALSE;
}

BOOL FollowerMon_IsTallGraphicsID(u16 graphicsID)
{
    return FollowerMon_IsTallGraphics(graphicsID);
}

// ENTRY P22 (2026-10-01): originally this block held FollowerMon_IsHGImportedGraphicsID, a plain switch
// over the 9 HG-sourced graphics IDs from ENTRY P17, used by FollowerMon_RefreshPalette to skip
// PersonalityRotatePalette for these species (the user asked for their colors to be an exact, unmodified
// copy of HG's own palette, not run through this project's personality-based rotation the way every native
// species still is). ENTRY P23 below subsumed that check into FollowerMon_GetHGPristinePalette's own
// NULL-vs-non-NULL return, so the separate function was removed rather than kept as dead code.

// ENTRY P23 (2026-10-01): ENTRY P22 still sourced the "pristine" palette at runtime via
// GetPlttDataVRAMBuffer(texture, 0) - NNS_G3dGetPlttDataByIdx's dictionary-index-0 lookup - and the user
// reported the result was still wrong ("red and orange/yellow instead of blue"), consistently regardless
// of which animation frame was showing. Extensive verification this entry (see Changelog.txt) ruled out
// every theory this assistant could test by reading code alone: manually parsed totodile.nsbtx's raw binary
// palette dictionary and confirmed index 0 genuinely is "tsure_poke0" at file-relative offset 0 (not index
// 1/"tsure_poke1", and not some other dictionary-order surprise); confirmed UpdateMaterialPlttAddresses'/
// UpdateMaterialTextureAddresses' "+=" pattern (src/billboard.c) does NOT accumulate across frames, because
// NNS_G3dBindMdlSet (called every single draw via Billboard_SetKeysAndBindModelSet, src/billboard.c:356-
// 361) re-derives each material's addresses fresh from the model resource's own pristine values every time;
// and confirmed nitrobtx - trusted, independent, purpose-built tooling for this exact file format - renders
// this same file+palette combination as a correct, recognizable blue Totodile (ENTRY P17's own investigation
// already established this). That combination of evidence means the raw file data is right and the runtime
// NNS_G3D palette-dictionary lookup path is the untrustworthy link - a code path this project's billboard
// system had literally never exercised with a >1-palette texture before ENTRY P17, since every native
// species' own texture has exactly one palette (offset 0 is a no-op either way for them, so a latent bug
// specific to multi-palette dictionaries would never have surfaced before now).
// FIX: stop asking NNS_G3D to resolve "palette 0" at runtime at all for these 9 species. The values below
// are the exact same bytes GetPlttDataVRAMBuffer(texture, 0) is SUPPOSED to return - extracted directly from
// each species' own res/graphics/field_sprites/pokemon_hg/<species>.nsbtx via tools/nitrobtx (dump
// --spritesheet --palettes-dir, the same trusted tool that renders these files correctly), converted from
// its JASC-PAL RGB888 output to BGR555 (the format every other palette in this file already uses, per
// pokemon_color_mod.c's own comment: 5 bits each of blue/green/red, bit 15 unused) with a plain
// round(channel * 31 / 255) per channel - not sourced from the SDK's own resource-dictionary code at all.
